+    impl Encoder for PrefillReasoningTokenizer {
+        fn encode(&self, _input: &str, _add_special_tokens: bool) -> Result<Encoding> {
+            Ok(Encoding::Plain(Vec::new()))
+        }
+
+        fn encode_batch(
+            &self,
+            inputs: &[&str],
+            _add_special_tokens: bool,
